// ---------------------------------------------------------------------
// FRAMEWORK FILE -- do not edit. Regenerated by the builder.
//
// Bridges the page to the native shell. The app bar and the bottom tab bar
// are real native widgets, so anything that changes a screen has to travel
// through here.
// ---------------------------------------------------------------------

const channel = window.NativeBridge;

function send(payload) {
  if (channel && typeof channel.postMessage === 'function') {
    channel.postMessage(JSON.stringify(payload));
  } else {
    // Running in a plain browser (not the app) -- log instead of failing.
    console.info('[bridge]', payload);
  }
}

// ---------------------------------------------------------------------
// Request/response channel.
//
// Everything above is fire-and-forget. Native UI -- pickers, dialogs,
// sheets -- has to answer, so those calls go out with an id and the shell
// calls window.__resolve(id, value) when the user is done. A cancelled
// dialog resolves with null, never rejects, so page code can just do:
//
//   const date = await native.pickDate();
//   if (!date) return;
// ---------------------------------------------------------------------
let requestId = 0;
const pending = new Map();

window.__resolve = (id, value) => {
  const resolve = pending.get(id);
  if (!resolve) return;
  pending.delete(id);
  resolve(value === undefined ? null : value);
};

function request(kind, options) {
  const id = ++requestId;
  return new Promise((resolve) => {
    pending.set(id, resolve);
    send({ action: 'ui', id, kind, options: options || {} });
    // In a plain browser there is no shell to answer, so nothing hangs.
    if (!channel || typeof channel.postMessage !== 'function') {
      window.__resolve(id, null);
    }
  });
}

export const native = {
  /** Push a screen as a native route, with a native transition + back. */
  /**
   * Presents a screen as a native bottom sheet. The page designs the content;
   * the shell gives it the drag handle, scrim, back-to-close and keyboard
   * handling. Resolves with what the sheet passes to closeSheet, or null when
   * the user dismisses it.
   *   const filters = await native.openSheet('filters', { data: current, size: 'half' });
   * size: 'half' (default) | 'full'
   */
  openSheet(screen, { data = null, size = 'half' } = {}) {
    return request('openSheet', { screen, data, size });
  },

  /** Inside a sheet: close it and hand `result` to whoever opened it. */
  closeSheet(result = null) {
    send({ action: 'closeSheet', result: result === undefined ? null : result });
  },

  /** Inside a sheet: the `data` it was opened with (null if none). */
  sheetData() {
    return request('sheetData', {});
  },

  /**
   * A badge on a bottom tab, e.g. a cart count. 0, '' or null removes it.
   *   native.setBadge('cart', 3)
   */
  setBadge(screen, value) {
    send({ action: 'setBadge', screen: String(screen), value: value == null ? '' : String(value) });
  },

  navigate(screenId, { title } = {}) {
    send({ action: 'navigate', screen: screenId, title });
  },

  /** Pop the current native route. */
  back() {
    send({ action: 'back' });
  },

  /** Switch the selected bottom tab. */
  selectTab(index) {
    send({ action: 'selectTab', index });
  },

  /** Native snackbar. */
  toast(message) {
    send({ action: 'toast', message });
  },

  /** Set the native AppBar title for the current screen. */
  setTitle(title) {
    send({ action: 'setTitle', title });
  },

  /** Native haptic tick. */
  haptic() {
    send({ action: 'haptic' });
  },

  /**
   * Ask to handle the back press yourself -- an unsaved form, a wizard step.
   * While on, back dispatches native:back to the page INSTEAD of leaving, so
   * the page must decide what happens:
   *   native.interceptBack(true);
   *   window.addEventListener('native:back', async () => {
   *     if (await native.confirm({ title: 'Discard changes?' })) {
   *       native.interceptBack(false);
   *       native.back();
   *     }
   *   });
   * Always turn it off again, or the screen cannot be left.
   */
  interceptBack(on) {
    send({ action: 'interceptBack', on: !!on });
  },

  /**
   * Ends the native pull-to-refresh spinner. Call it when the reload is
   * actually done:
   *   window.addEventListener('native:refresh', async () => {
   *     await reload();
   *     native.refreshDone();
   *   });
   */
  refreshDone() {
    send({ action: 'refreshDone' });
  },

  /** Opens the native side menu, if the app has one. */
  openDrawer() {
    send({ action: 'openDrawer' });
  },

  closeDrawer() {
    send({ action: 'closeDrawer' });
  },

  /**
   * Listen for AppBar / drawer buttons that have no screen attached.
   *
   *   native.onAction('save', () => save());
   *
   * The shell dispatches native:action with the button's id, so page code
   * decides what the button means.
   */
  onAction(id, handler) {
    window.addEventListener('native:action', (event) => {
      if (event.detail && event.detail.id === id) handler();
    });
  },

  // -------------------------------------------------------------------
  // Native UI. Use these INSTEAD of web equivalents: never window.alert /
  // confirm / prompt, never <input type="date"> or <input type="time">,
  // never <select>, and never a hand-built HTML modal, sheet or dropdown.
  //
  // Every one of them is styled from the manifest's `components` block, and
  // any single call can override any of those keys with { style: {...} },
  // so they always match the app's design.
  // -------------------------------------------------------------------

  /**
   * Native date picker. Resolves 'YYYY-MM-DD', or null if cancelled.
   *   native.pickDate({ initial: '2026-08-25', min: '2026-01-01', title: 'Due date' })
   */
  pickDate(options) {
    return request('date', options);
  },

  /** Native time picker. Resolves 'HH:mm' (24h), or null. */
  pickTime(options) {
    return request('time', options);
  },

  /** Native range picker. Resolves { start, end } as 'YYYY-MM-DD', or null. */
  pickDateRange(options) {
    return request('dateRange', options);
  },

  /**
   * Native confirmation dialog. Resolves true / false.
   *   await native.confirm({ title: 'Delete order?', message: '...',
   *                          confirmLabel: 'Delete', destructive: true })
   */
  confirm(options) {
    return request('confirm', options);
  },

  /** Native alert with a single button. Resolves true when dismissed. */
  alert(options) {
    return request('alert', options);
  },

  /** Native single-field dialog. Resolves the string, or null if cancelled. */
  prompt(options) {
    return request('prompt', options);
  },

  /**
   * Native bottom sheet of choices. Resolves the chosen item's id, or null.
   *   native.actionSheet({ title: 'Order', items: [
   *     { id: 'edit', label: 'Edit', icon: 'settings' },
   *     { id: 'delete', label: 'Delete', icon: 'info', destructive: true } ] })
   */
  actionSheet(options) {
    return request('actionSheet', options);
  },

  /**
   * Native single-choice list -- the replacement for <select>. Resolves the
   * chosen value, or null.
   *   native.select({ title: 'Status', selected: 'open',
   *                   options: [{ value: 'open', label: 'Open' }, ...] })
   */
  select(options) {
    return request('select', options);
  },

  /** Native multi-choice list. Resolves an array of values, or null. */
  multiSelect(options) {
    return request('multiSelect', options);
  },

  /**
   * Native snackbar with an optional action. Resolves true when the action
   * was tapped, false otherwise -- the undo pattern:
   *   if (await native.snackbar({ message: 'Deleted', actionLabel: 'Undo' })) restore();
   */
  snackbar(options) {
    return request('snackbar', options);
  },

  /** Blocking native progress overlay. Always pair the two calls. */
  loading(on, options) {
    send({ action: 'loading', on: !!on, options: options || {} });
  },

  // -------------------------------------------------------------------
  // Media, files and sharing. Same rule as above: use these, never a web
  // stand-in. No <input type="file"> for photos, no <a download> for
  // exports, no <a target="_blank"> for external links, no navigator.share.
  // -------------------------------------------------------------------

  /**
   * Native image picker. Resolves { dataUrl, width, height, sizeKb, name },
   * or null if cancelled. The image is downscaled and re-encoded natively,
   * so what you get back is small enough to store.
   *   const photo = await native.pickImage({ source: 'camera', maxSize: 1024 });
   *   if (photo) img.src = photo.dataUrl;
   */
  pickImage(options) {
    return request('pickImage', options);
  },

  /** Several images at once. Resolves an array of the same objects, or null. */
  pickImages(options) {
    return request('pickImages', options);
  },

  /**
   * Native document picker. Resolves { name, mimeType, size, dataUrl, text? },
   * or null. Text-ish files also come back decoded as `text`.
   *   const csv = await native.pickFile({ accept: ['text/csv'], asText: true });
   */
  pickFile(options) {
    return request('pickFile', options);
  },

  /**
   * Saves a file wherever the user chooses -- the export path. Pass `text`
   * or a `dataUrl`. Resolves true when written.
   *   await native.saveFile({ name: 'orders.csv', mimeType: 'text/csv', text: csv });
   */
  saveFile(options) {
    return request('saveFile', options);
  },

  /**
   * System share sheet. Any of text, url and file.
   *   await native.share({ title: 'Invoice', text: 'Invoice #42',
   *                        file: { name: 'invoice.pdf', dataUrl } });
   */
  share(options) {
    return request('share', options);
  },

  /**
   * Opens an EXTERNAL link in the browser or the app that handles it (tel:,
   * mailto:, https:, geo:, whatsapp:). Resolves false when nothing can.
   * In-app navigation still goes through native.navigate.
   */
  openUrl(url) {
    return request('openUrl', { url });
  },

  // -------------------------------------------------------------------
  // Permissions. The shell asks for what a feature needs at the moment it
  // is used -- taking a photo prompts for the camera by itself -- so page
  // code only needs these to ask early, or to explain why something is
  // unavailable.
  // -------------------------------------------------------------------

  /**
   * Prompts if needed. Resolves { granted, status } where status is
   * 'granted' | 'denied' | 'unavailable' ('unavailable' means the app was
   * built without that capability declared).
   *   const { granted } = await native.requestPermission('camera');
   */
  requestPermission(id) {
    return request('requestPermission', { id });
  },

  /** Same shape, without prompting. */
  permissionStatus(id) {
    return request('permissionStatus', { id });
  },

  // -------------------------------------------------------------------
  // The app itself: version, secrets, the store, and links that open it.
  // -------------------------------------------------------------------

  /**
   * { package, version, build, installedAt, updatedAt, debug }. Show the
   * real version rather than hardcoding one that goes stale.
   */
  appInfo() {
    return request('appInfo', {});
  },

  /**
   * Encrypted storage, for a token or a PIN. Separate from native.storage
   * ON PURPOSE: that one is injected into every page, so anything in it is
   * readable by any screen's JavaScript. This is not.
   *   await native.secure.set('token', jwt);
   *   const jwt = await native.secure.get('token');   // string | null
   */
  secure: {
    set(key, value) {
      return request('secureSet', { key, value });
    },
    get(key) {
      return request('secureGet', { key });
    },
    remove(key) {
      return request('secureRemove', { key });
    },
  },

  /**
   * The Play in-app review prompt. Play decides whether it actually appears
   * (there is a quota, and it never shows for a sideloaded build) and gives
   * no way to find out, so this resolves { ok: true, status: 'asked' } at
   * best -- never gate anything on it, and never nag.
   */
  requestReview() {
    return request('requestReview', {});
  },

  /** Opens this app's store listing, or another package's. */
  openStorePage(packageName) {
    return request('openStorePage', packageName ? { package: packageName } : {});
  },

  // -------------------------------------------------------------------
  // AdMob. The banner is configured on the app (set_ads) and drawn by the
  // shell -- pages never place one. These two are the ones a page decides
  // the moment for.
  // -------------------------------------------------------------------

  /**
   * A full-screen ad between two pieces of content. Resolves { shown } --
   * or { error: 'unavailable' } when the app has no ads, or nothing filled.
   * NEVER block anything on it: an unfilled ad is normal.
   *   await native.showInterstitial();
   *   native.navigate('results');
   */
  showInterstitial() {
    return request('showInterstitial', {});
  },

  /**
   * A rewarded ad. Resolves { earned, amount, type }; `earned` is false when
   * the user closed it early, and nothing should be granted in that case.
   *   const { earned } = await native.showRewarded();
   *   if (earned) unlock();
   */
  showRewarded() {
    return request('showRewarded', {});
  },

  /** { available, test } -- whether this build can show ads at all. */
  adsStatus() {
    return request('adsStatus', {});
  },

  /**
   * The link the app was launched with, if any: { url, scheme, host, path,
   * query } or null. Links that arrive while the app is open come through
   * the native:deeplink event instead.
   */
  initialLink() {
    return request('initialLink', {});
  },

  // -------------------------------------------------------------------
  // Device capabilities. Again: these, not a web equivalent. No
  // navigator.geolocation, no navigator.clipboard, no navigator.vibrate,
  // no <a href="tel:"> / "mailto:" / "sms:" links.
  // -------------------------------------------------------------------

  /**
   * One location fix. Prompts for the permission by itself.
   * Resolves { lat, lng, accuracy, at } or { error } -- 'denied',
   * 'unavailable' (location off / no provider) or 'timeout'.
   */
  location(options) {
    return request('location', options);
  },

  /**
   * Continuous updates. The shell dispatches native:location with the same
   * shape until you stop it:
   *   window.addEventListener('native:location', e => draw(e.detail));
   *   await native.watchLocation(true, { minMs: 5000, minMeters: 10 });
   */
  watchLocation(on, options) {
    return request('watchLocation', { on: !!on, ...(options || {}) });
  },

  /** Connectivity now: { online, type }. Also fires native:network on change. */
  network() {
    return request('network', {});
  },

  /** Start / stop native:network events. */
  watchNetwork(on) {
    return request('watchNetwork', { on: !!on });
  },

  /** Copies text. Resolves true. */
  copy(text) {
    return request('copy', { text });
  },

  /** Reads the clipboard. Resolves the string, or null when it holds no text. */
  paste() {
    return request('paste', {});
  },

  /**
   * Vibration pattern in milliseconds, e.g. [0, 120] or [0, 60, 80, 60].
   * Needs the 'vibrate' capability declared.
   */
  vibrate(pattern) {
    return request('vibrate', { pattern: pattern || [0, 60] });
  },

  /** Opens the dialler with the number ready (does NOT place the call). */
  call(number) {
    return request('call', { number });
  },

  /** Opens the SMS app. */
  sms(options) {
    return request('sms', options);
  },

  /** Opens the mail app. `to` may be a string or an array. */
  email(options) {
    return request('email', options);
  },

  /** Opens a WhatsApp chat with the message prefilled. */
  whatsapp(options) {
    return request('whatsapp', options);
  },

  /** Opens the maps app: pass { lat, lng, label } or { query }. */
  openMaps(options) {
    return request('openMaps', options);
  },

  /**
   * Native contact picker. Resolves { name, phone } or null. Needs no
   * permission: the picker grants access to the one contact chosen.
   */
  pickContact() {
    return request('pickContact', {});
  },

  /**
   * Opens the calendar app with a new event prefilled. Dates are
   * 'YYYY-MM-DD' or 'YYYY-MM-DDTHH:mm'.
   *   await native.addCalendarEvent({ title, start, end, location, notes });
   */
  addCalendarEvent(options) {
    return request('addCalendarEvent', options);
  },

  /**
   * Fingerprint / face check. Resolves { ok, status } where status is
   * 'success' | 'failed' | 'cancelled' | 'unavailable' | 'not_enrolled'.
   */
  biometric(options) {
    return request('biometric', options);
  },

  /**
   * Native barcode / QR scanner. Resolves { value, format } or null when
   * cancelled, { error: 'unavailable' } where the scanner is not supported.
   */
  scanBarcode(options) {
    return request('scanBarcode', options);
  },

  // -------------------------------------------------------------------
  // Notifications and scheduling. Never the web Notification API or
  // setTimeout for a reminder: a page timer dies the moment the app is
  // closed, which is exactly when a reminder has to survive.
  // -------------------------------------------------------------------

  /**
   * Shows a notification now, as a banner over whatever is on screen.
   * Prompts for permission the first time. Resolves { ok, status } --
   * 'shown' | 'denied' | 'unavailable'.
   *   await native.notify({ title: 'Saved', body: 'Order #42 stored',
   *                         id: 'order-42', data: { screen: 'orders' } });
   * Every notification is a heads-up banner, the way a message from any
   * other app arrives. There is no quiet variant.
   */
  notify(options) {
    return request('notify', options);
  },

  /**
   * Schedules one for later. Give `at` ('YYYY-MM-DDTHH:mm', local) or
   * `inMs`. Survives the app being closed; does NOT survive a reboot.
   * Resolves { ok, id, status } -- 'scheduled' | 'denied' | 'past'.
   *   await native.scheduleNotification({ id: 'pill', title: 'Take your pill',
   *                                       at: '2026-09-01T09:00' });
   */
  scheduleNotification(options) {
    return request('scheduleNotification', options);
  },

  /** Cancels a scheduled or shown notification by id. Resolves true. */
  cancelNotification(id) {
    return request('cancelNotification', { id });
  },

  /** Cancels everything this app scheduled or showed. */
  cancelAllNotifications() {
    return request('cancelAllNotifications', {});
  },

  /** { granted, status } without prompting. */
  notificationsEnabled() {
    return request('notificationsEnabled', {});
  },

  /**
   * Keeps the screen on while a screen needs it (a recipe, a workout, a
   * scanner view). Always turn it back off.
   */
  keepAwake(on) {
    return request('keepAwake', { on: !!on });
  },

  /**
   * Tapping a notification opens the app and dispatches native:notification
   * with { id, data } -- the `data` you passed when creating it, so the page
   * can open the right screen:
   *   window.addEventListener('native:notification', e => {
   *     if (e.detail.data.screen) native.navigate(e.detail.data.screen);
   *   });
   */

  /**
   * Firebase push token for this install. Resolves { token } or
   * { error: 'unavailable' } -- unavailable means the app was built without
   * push, or without a google-services.json. Send the token to your server;
   * it is what a push is addressed to.
   */
  pushToken() {
    return request('pushToken', {});
  },

  /** Topic subscriptions, for broadcasting without storing tokens. */
  subscribeTopic(topic) {
    return request('subscribeTopic', { topic });
  },

  unsubscribeTopic(topic) {
    return request('unsubscribeTopic', { topic });
  },

  /**
   * An arriving push is shown as a banner automatically, and while the app is
   * open it also reaches the page:
   *   window.addEventListener('native:push', e => refresh(e.detail.data));
   *   window.addEventListener('native:pushtoken', e => send(e.detail.token));
   */
};

// Any element with data-nav="screenId" navigates natively -- no <a href>
// needed, and no full page load.
document.addEventListener('click', (event) => {
  const target = event.target.closest('[data-nav]');
  if (!target) return;
  event.preventDefault();
  native.haptic();
  native.navigate(target.dataset.nav, { title: target.dataset.navTitle });
});

// ---------------------------------------------------------------------
// Storage.
//
// NOT localStorage. Two failure modes made that unusable:
//   * Chromium batches localStorage writes and flushes on pause/idle, so
//     killing the app shortly after a write silently loses it.
//   * It is partitioned by origin (which includes the port), so any port
//     change orphans everything previously written.
//
// Instead: the server injects window.__STORE__ into this page before any
// script runs, so reads are synchronous, and writes go through the native
// bridge to a file that is flushed immediately.
// ---------------------------------------------------------------------
// Always read through this, never a cached reference: the shell REPLACES
// window.__STORE__ with fresh data before dispatching native:resume. A held
// reference would keep showing the snapshot from page load, so a screen would
// never see data written by another screen.
function currentStore() {
  if (!window.__STORE__) window.__STORE__ = {};
  return window.__STORE__;
}

native.storage = {
  /** Synchronous read of the value saved for this app. */
  get(key, fallback = null) {
    const store = currentStore();
    return Object.prototype.hasOwnProperty.call(store, key) ? store[key] : fallback;
  },

  /** Persists immediately; survives the app being killed. */
  set(key, value) {
    currentStore()[key] = value;
    send({ action: 'store', key, value: JSON.stringify(value) });
    return true;
  },

  remove(key) {
    delete currentStore()[key];
    send({ action: 'store', key, value: null });
  },
};

// ---------------------------------------------------------------------
// Backend: native.db and native.auth.
//
// Backed by the user's own Supabase project, linked from the builder and
// recorded in project.json (url + publishable key -- public by design; row-level
// security protects the data). The client library is bundled at
// shared/vendor/supabase.js and loaded on first use, so an app that never
// touches the backend never pays for it.
//
// Every user gets an anonymous session on first use, so per-user data works
// without a login screen; signUp later upgrades that same user in place.
// The session is kept in native.storage, not localStorage (see Storage above).
//
// Tables are aab_<prefix>_<collection>, created by the builder's set_backend.
// Queries run through SECURITY INVOKER functions, so RLS always applies.
// ---------------------------------------------------------------------
let backendPromise = null;
let sessionPromise = null;

function loadScript(src) {
  return new Promise((resolve, reject) => {
    const tag = document.createElement('script');
    tag.src = src;
    tag.onload = resolve;
    tag.onerror = () => reject(new Error('Could not load ' + src));
    document.head.appendChild(tag);
  });
}

// supabase-js accepts any synchronous getItem/setItem/removeItem store.
const authStorage = {
  getItem: (key) => {
    const value = native.storage.get('__auth:' + key, null);
    return value == null ? null : String(value);
  },
  setItem: (key, value) => { native.storage.set('__auth:' + key, value); },
  removeItem: (key) => { native.storage.remove('__auth:' + key); },
};

function backend() {
  if (backendPromise) return backendPromise;
  backendPromise = (async () => {
    const res = await fetch(new URL('../project.json', import.meta.url), { cache: 'no-store' });
    const manifest = await res.json();
    const b = manifest.backend || {};
    if (b.provider !== 'supabase' || !b.url || !b.publicKey || !b.prefix) {
      throw new Error('This app has no backend yet. Link Supabase from the Backend button in the builder.');
    }
    if (!window.supabase) await loadScript(new URL('./vendor/supabase.js', import.meta.url).href);
    const client = window.supabase.createClient(b.url, b.publicKey, {
      auth: {
        storage: authStorage,
        persistSession: true,
        autoRefreshToken: true,
        detectSessionInUrl: false,
      },
    });
    return { client, prefix: b.prefix };
  })();
  backendPromise.catch(() => { backendPromise = null; });
  return backendPromise;
}

async function ready() {
  const b = await backend();
  if (!sessionPromise) {
    sessionPromise = (async () => {
      const { data } = await b.client.auth.getSession();
      if (!data.session) {
        const { error } = await b.client.auth.signInAnonymously();
        if (error) throw error;
      }
    })();
    sessionPromise.catch(() => { sessionPromise = null; });
  }
  await sessionPromise;
  return b;
}

function fail(error) {
  const e = new Error((error && error.message) || String(error));
  if (error && error.code) e.code = error.code;
  throw e;
}

function tableOf(b, collection) {
  if (!/^[a-z][a-z0-9_]{0,29}$/.test(String(collection))) {
    throw new Error('Unknown collection: ' + collection);
  }
  return 'aab_' + b.prefix + '_' + collection;
}

function toDoc(row) {
  if (!row) return null;
  return Object.assign({}, row.data, {
    id: row.id, owner: row.owner, createdAt: row.created_at, updatedAt: row.updated_at,
  });
}

// Server-owned fields never go into the document body.
function body(data) {
  const copy = JSON.parse(JSON.stringify(data || {}));
  delete copy.id; delete copy.owner; delete copy.createdAt; delete copy.updatedAt;
  return copy;
}

function toUser(user) {
  if (!user) return null;
  return { id: user.id, email: user.email || null, anonymous: !!user.is_anonymous };
}

native.db = {
  async add(collection, data) {
    const b = await ready();
    const { data: row, error } = await b.client
      .from(tableOf(b, collection)).insert({ data: body(data) }).select().single();
    if (error) fail(error);
    return toDoc(row);
  },

  async get(collection, id) {
    const b = await ready();
    const { data: row, error } = await b.client
      .from(tableOf(b, collection)).select().eq('id', id).maybeSingle();
    if (error) fail(error);
    return toDoc(row);
  },

  async list(collection, options = {}) {
    const b = await ready();
    let order = options.orderBy || '';
    let desc = false;
    if (order.startsWith('-')) { desc = true; order = order.slice(1); }
    const { data, error } = await b.client.rpc('aab_list', {
      p_table: tableOf(b, collection),
      p_where: options.where || {},
      p_order: order || null,
      p_desc: order ? desc : !!options.desc,
      p_limit: options.limit || 100,
      p_offset: options.offset || 0,
      p_mine: !!options.mine,
    });
    if (error) fail(error);
    // PostgREST may wrap each value of a setof-jsonb function in { aab_list: … }.
    return (data || []).map((row) =>
      row && typeof row === 'object' && 'aab_list' in row && Object.keys(row).length === 1 ? row.aab_list : row);
  },

  async count(collection, options = {}) {
    const b = await ready();
    const { data, error } = await b.client.rpc('aab_count', {
      p_table: tableOf(b, collection),
      p_where: options.where || {},
      p_mine: !!options.mine,
    });
    if (error) fail(error);
    return Number(data) || 0;
  },

  async update(collection, id, patch) {
    const b = await ready();
    const { data, error } = await b.client.rpc('aab_patch', {
      p_table: tableOf(b, collection), p_id: id, p_patch: body(patch),
    });
    if (error) fail(error);
    if (!data) throw new Error('Not found, or you are not allowed to change it.');
    return data;
  },

  async remove(collection, id) {
    const b = await ready();
    const { data, error } = await b.client
      .from(tableOf(b, collection)).delete().eq('id', id).select('id');
    if (error) fail(error);
    return Array.isArray(data) && data.length > 0;
  },

  /** Calls callback() whenever the collection changes. Returns a stop function. */
  watch(collection, callback) {
    let channel = null;
    let stopped = false;
    ready().then((b) => {
      if (stopped) return;
      channel = b.client
        .channel('watch:' + collection + ':' + Math.random().toString(36).slice(2))
        .on('postgres_changes', { event: '*', schema: 'public', table: tableOf(b, collection) },
          () => { try { callback(); } catch (e) { console.error(e); } })
        .subscribe();
    }).catch((e) => console.warn('[native.db.watch]', e.message));
    return () => {
      stopped = true;
      if (channel) channel.unsubscribe();
    };
  },
};

// Files: Supabase Storage, two buckets per app. A path returned by upload
// ("public/<uid>/..." or "private/<uid>/...") is what goes into a row; url()
// turns it back into something an <img> can show.
function bucketFor(b, path) {
  const visibility = String(path).split('/')[0];
  if (visibility !== 'public' && visibility !== 'private') throw new Error('Not a file path: ' + path);
  return { bucket: 'aab_' + b.prefix + '_' + visibility, key: String(path).slice(visibility.length + 1) };
}

function dataUrlToBlob(dataUrl) {
  const [head, body] = String(dataUrl).split(',');
  const mime = (head.match(/data:([^;]+)/) || [])[1] || 'application/octet-stream';
  const bin = atob(body || '');
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new Blob([bytes], { type: mime });
}

const EXT = { 'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp', 'image/gif': 'gif',
  'application/pdf': 'pdf', 'text/plain': 'txt', 'text/csv': 'csv' };

async function signedUrl(b, path) {
  const { bucket, key } = bucketFor(b, path);
  if (bucket.endsWith('_public')) return b.client.storage.from(bucket).getPublicUrl(key).data.publicUrl;
  const { data, error } = await b.client.storage.from(bucket).createSignedUrl(key, 3600);
  if (error) fail(error);
  return data.signedUrl;
}

native.files = {
  /**
   * Uploads a picked image/file ({ dataUrl, name?, mimeType? }), a data: URL,
   * or a Blob. Public by default. Resolves { path, url }; keep `path` in rows.
   */
  async upload(file, options = {}) {
    const b = await ready();
    const blob = file instanceof Blob ? file
      : dataUrlToBlob(typeof file === 'string' ? file : (file && file.dataUrl));
    if (blob.size > 10 * 1024 * 1024) throw new Error('File is larger than 10 MB.');
    const visibility = options.public === false ? 'private' : 'public';
    const { data: session } = await b.client.auth.getSession();
    const uid = session.session.user.id;
    const name = (file && file.name) || '';
    const ext = (name.includes('.') ? name.split('.').pop() : EXT[blob.type]) || 'bin';
    const key = uid + '/' + Date.now() + '-' + Math.random().toString(36).slice(2, 8) + '.' + ext.toLowerCase();
    const { error } = await b.client.storage.from('aab_' + b.prefix + '_' + visibility)
      .upload(key, blob, { contentType: blob.type, upsert: false });
    if (error) fail(error);
    const path = visibility + '/' + key;
    return { path, url: await signedUrl(b, path) };
  },

  /** A URL for a stored path. Private files get a link valid for one hour. */
  async url(path) {
    const b = await ready();
    return signedUrl(b, path);
  },

  /** Deletes a file you uploaded. Resolves true when it was removed. */
  async remove(path) {
    const b = await ready();
    const { bucket, key } = bucketFor(b, path);
    const { data, error } = await b.client.storage.from(bucket).remove([key]);
    if (error) fail(error);
    return Array.isArray(data) && data.length > 0;
  },
};

native.auth = {
  async user() {
    const b = await ready();
    const { data } = await b.client.auth.getSession();
    return toUser(data.session && data.session.user);
  },

  /** Upgrades the current anonymous user in place, so their data stays theirs. */
  async signUp(email, password) {
    const b = await ready();
    const { data: current } = await b.client.auth.getSession();
    const user = current.session && current.session.user;
    if (user && user.is_anonymous) {
      const { data, error } = await b.client.auth.updateUser({ email, password });
      if (error) fail(error);
      return toUser(data.user);
    }
    const { data, error } = await b.client.auth.signUp({ email, password });
    if (error) fail(error);
    return toUser(data.user);
  },

  async signIn(email, password) {
    const b = await backend();
    const { data, error } = await b.client.auth.signInWithPassword({ email, password });
    if (error) fail(error);
    sessionPromise = Promise.resolve();
    return toUser(data.user);
  },

  /** Emails a numeric reset code (6–10 digits). Resolves true (also for unknown emails -- no account probing). */
  async resetPassword(email) {
    const b = await backend();
    const { error } = await b.client.auth.resetPasswordForEmail(String(email).trim());
    if (error) fail(error);
    return true;
  },

  /** Checks the emailed code, sets the new password and signs the user in. */
  async confirmReset(email, code, newPassword) {
    const b = await backend();
    const { error } = await b.client.auth.verifyOtp({
      email: String(email).trim(), token: String(code).trim(), type: 'recovery',
    });
    if (error) fail(error);
    const { data, error: updateError } = await b.client.auth.updateUser({ password: newPassword });
    if (updateError) fail(updateError);
    sessionPromise = Promise.resolve();
    return toUser(data.user);
  },

  async signOut() {
    const b = await backend();
    await b.client.auth.signOut();
    sessionPromise = null;
    return true;
  },

  /**
   * True when the signed-in user is one of this app's admins (set from the
   * builder's Online data panel). Admins can change 'admin' collections and
   * see every row of 'submissions' collections.
   */
  async isAdmin() {
    const b = await ready();
    const { data, error } = await b.client.rpc('aab_is_admin', { p_prefix: b.prefix });
    if (error) fail(error);
    return !!data;
  },

  /** callback(user) on sign-in, sign-out and upgrade. Returns a stop function. */
  onChange(callback) {
    let sub = null;
    let stopped = false;
    backend().then((b) => {
      if (stopped) return;
      sub = b.client.auth.onAuthStateChange((_event, session) => {
        try { callback(toUser(session && session.user)); } catch (e) { console.error(e); }
      }).data.subscription;
    }).catch((e) => console.warn('[native.auth.onChange]', e.message));
    return () => {
      stopped = true;
      if (sub) sub.unsubscribe();
    };
  },
};

// ---------------------------------------------------------------------
// Images written as <img data-src="..."> load themselves.
//
// Screens are told to call their own loadImages() after rendering; one that
// forgets would show empty photos forever. A page's own loadImages() runs
// first (it is synchronous, this observer fires after), so this only picks up
// what was missed. Same classes: .loaded on load, .failed on the .img-box.
// ---------------------------------------------------------------------
function loadDataSrcImages(root) {
  if (!root || !root.querySelectorAll) return;
  const list = root.matches && root.matches('img[data-src]') ? [root] : root.querySelectorAll('img[data-src]');
  list.forEach((img) => {
    const src = img.getAttribute('data-src');
    if (!src) return;
    img.addEventListener('load', () => img.classList.add('loaded'), { once: true });
    img.addEventListener('error', () => {
      const box = img.closest('.img-box');
      if (box) box.classList.add('failed');
    }, { once: true });
    img.src = src;
    img.removeAttribute('data-src');
  });
}
new MutationObserver((mutations) => {
  for (const m of mutations) {
    for (const node of m.addedNodes) if (node.nodeType === 1) loadDataSrcImages(node);
    if (m.type === 'attributes' && m.target.nodeType === 1) loadDataSrcImages(m.target);
  }
}).observe(document.documentElement, { childList: true, subtree: true, attributes: true, attributeFilter: ['data-src'] });
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => loadDataSrcImages(document));
} else {
  loadDataSrcImages(document);
}

// ---------------------------------------------------------------------
// Ripple on press, matching the native button feel.
//
// Applied to .btn and anything marked [data-ripple]. Uses pointerdown so it
// fires the instant the finger lands rather than on click release.
// ---------------------------------------------------------------------
const prefersReducedMotion =
  window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

document.addEventListener('pointerdown', (event) => {
  if (prefersReducedMotion) return;

  const target = event.target.closest('.btn, [data-ripple]');
  if (!target || target.disabled) return;

  const rect = target.getBoundingClientRect();
  // Diameter covers the far corner from wherever the finger landed.
  const size = Math.max(rect.width, rect.height) * 2;

  const ripple = document.createElement('span');
  ripple.className = 'ripple';
  ripple.style.width = size + 'px';
  ripple.style.height = size + 'px';
  ripple.style.left = (event.clientX - rect.left - size / 2) + 'px';
  ripple.style.top = (event.clientY - rect.top - size / 2) + 'px';

  target.appendChild(ripple);
  ripple.addEventListener('animationend', () => ripple.remove());
}, true);

// ---------------------------------------------------------------------
// Edit mode.
//
// OFF by default: taps behave normally and the app is fully usable. When the
// builder turns it on (the pencil button in the preview), a tap stops
// activating the element and instead reports what was tapped, so a change
// request can name the exact screen and markup.
// ---------------------------------------------------------------------
let editMode = false;

window.__setEditMode = (on) => {
  editMode = !!on;
  document.body.classList.toggle('edit-mode', editMode);
  if (!editMode) {
    document.querySelectorAll('.edit-hit').forEach((n) => n.classList.remove('edit-hit'));
  }
};

/** A short, stable-ish CSS selector for the element. */
function describeSelector(el) {
  if (el.id) return '#' + el.id;

  const classes = (el.getAttribute('class') || '')
    .split(/\s+/)
    .filter((c) => c && c !== 'ripple' && c !== 'edit-hit')
    .slice(0, 3);

  let selector = el.tagName.toLowerCase();
  if (classes.length) selector += '.' + classes.join('.');

  // Disambiguate repeated rows, e.g. the third .list-item.
  const parent = el.parentElement;
  if (parent) {
    const twins = [...parent.children].filter((c) => c.tagName === el.tagName);
    if (twins.length > 1) selector += ':nth-of-type(' + (twins.indexOf(el) + 1) + ')';
  }
  return selector;
}

document.addEventListener('click', (event) => {
  if (!editMode) return;

  // Swallow the tap: in edit mode the user is pointing, not using the app.
  event.preventDefault();
  event.stopPropagation();

  // Exactly what was tapped. Walking up to a container was wrong: tapping a
  // title inside a card reported the card, so edits hit the wrong element.
  const target = event.target instanceof Element ? event.target : document.body;

  document.querySelectorAll('.edit-hit').forEach((n) => n.classList.remove('edit-hit'));
  target.classList.add('edit-hit');

  // A few ancestors, so the model can tell two identical elements apart even
  // though the reported markup is only this one.
  const path = [];
  let node = target.parentElement;
  while (node && node !== document.body && path.length < 3) {
    path.unshift(describeSelector(node));
    node = node.parentElement;
  }

  const html = target.outerHTML || '';
  send({
    action: 'inspect',
    selector: describeSelector(target),
    path: path.join(' > '),
    tag: target.tagName.toLowerCase(),
    text: (target.innerText || target.textContent || '').trim().slice(0, 120),
    // Trimmed: enough for the model to write an exact patch without paying
    // for a whole screen of markup.
    html: html.length > 900 ? html.slice(0, 900) + '\n<!-- truncated -->' : html,
  });
}, true);

// ---------------------------------------------------------------------
// Events the native chrome sends a screen. All of them are plain window
// events, so a screen listens for only what it uses:
//
//   native:resume        the screen is visible again -- re-read your data
//   native:action        an app bar button, drawer item, FAB or menu item
//   native:search        the app bar search query changed  (detail.query)
//   native:searchsubmit  the keyboard's search key         (detail.query)
//   native:refresh       pull-to-refresh started -- call native.refreshDone()
//   native:back          back was pressed while interceptBack(true)
//   native:notification  a notification was tapped         (detail.id, .data)
//   native:push          a push arrived                    (detail.data)
//   native:deeplink      a link opened the app             (detail.url, .path)
//   native:location      a location fix, while watching
//   native:network       connectivity changed              (detail.online)
// ---------------------------------------------------------------------

// ---------------------------------------------------------------------
// native.payments: Stripe / PayPal checkout through the app's own backend.
//
// The builder's Payments panel installs a function ("aab-pay") in the app's
// Supabase project and stores the provider keys there as secrets, so no key is
// ever in the app. Prices are read on the server from the app's own table
// (data.price of each row) -- the page only says WHICH rows and how many.
//
//   const r = await native.payments.checkout({ collection: 'products',
//                                              items: [{ id, quantity }] });
//   // r.status: 'paid' | 'cancelled' | 'pending' | 'failed'
//
// The buyer pays on Stripe's / PayPal's own page in a browser tab; the promise
// settles when the payment is confirmed server-side or the buyer comes back
// without paying.
// ---------------------------------------------------------------------
async function payCall(action, payload) {
  const b = await ready();
  const { data, error } = await b.client.functions.invoke('aab-pay', { body: Object.assign({ action, prefix: b.prefix }, payload) });
  if (error) {
    let message = error.message;
    try {
      const body = await error.context.json();
      if (body && body.error) message = body.error;
    } catch (e) { /* keep the generic message */ }
    throw new Error(message);
  }
  return data;
}

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// After the buyer is back, how long to keep checking before calling it
// abandoned: a provider can take several seconds to confirm (PayPal captures
// after the redirect), and a payment confirmed later is still recovered.
const PAY_GRACE_MS = 45000;
const PAY_OPEN_KEY = '__pay:open';

async function waitForPayment(paymentId) {
  const deadline = Date.now() + 15 * 60 * 1000;
  let back = null;   // when the buyer returned to the app from the payment page
  let left = document.hidden;
  // In the builder's simulator checkout runs in an in-phone sheet, and a
  // provider's own pop-up (PayPal login, card checks) can hide the tab: only
  // closing the sheet counts as coming back there.
  const onVisibility = () => {
    if (window.__AAB_PREVIEW__) return;
    if (document.hidden) left = true;
    else if (left) back = Date.now();
  };
  document.addEventListener('visibilitychange', onVisibility);
  // The builder's simulator shows checkout in an in-phone browser instead of
  // leaving the page; closing it is the same as coming back to the app.
  const onClosed = () => { back = Date.now(); };
  window.addEventListener('native:browserclosed', onClosed);
  try {
    while (Date.now() < deadline) {
      await sleep(back ? 2000 : 3000);
      let state;
      try {
        state = await payCall('status', { paymentId });
      } catch (e) {
        continue;   // a blip; keep waiting
      }
      if (state.status !== 'pending') return state.status;
      // Back in the app for a while and still not paid: they closed the page.
      if (back && Date.now() - back > PAY_GRACE_MS) return 'cancelled';
    }
    return 'pending';
  } finally {
    document.removeEventListener('visibilitychange', onVisibility);
    window.removeEventListener('native:browserclosed', onClosed);
  }
}

native.payments = {
  /** The providers set up for this app: [] | ['stripe'] | ['paypal'] | both. */
  async providers() {
    try {
      return (await payCall('providers', {})).providers || [];
    } catch (e) {
      return [];
    }
  },

  async checkout({ items, collection = 'products', provider } = {}) {
    let chosen = provider;
    if (!chosen) {
      const list = await native.payments.providers();
      if (!list.length) {
        throw new Error('Payments are not set up for this app yet. Connect Stripe or PayPal from the Payments button in the builder.');
      }
      chosen = list.length === 1 ? list[0] : await native.actionSheet({
        title: 'Pay with',
        items: [{ id: 'stripe', label: 'Card', icon: 'shopping_cart' }, { id: 'paypal', label: 'PayPal', icon: 'star' }],
      });
      if (!chosen) return { status: 'cancelled' };
    }
    native.loading(true, { message: 'Opening secure checkout…' });
    let started;
    try {
      // In the builder's simulator Stripe's own page cannot be framed, so ask for
      // the embeddable checkout, which opens inside the phone.
      started = await payCall('checkout', { items, collection, provider: chosen, embedded: !!window.__AAB_PREVIEW__ });
    } finally {
      native.loading(false);
    }
    const result = { paymentId: started.paymentId, amount: started.amount, currency: started.currency, provider: chosen };
    // Remembered until settled, so recover() can pick up a payment that is
    // confirmed after this call gave up waiting.
    native.storage.set(PAY_OPEN_KEY, Object.assign({ at: Date.now() }, result));
    await native.openUrl(started.url);
    const status = await waitForPayment(started.paymentId);
    if (status === 'paid' || status === 'failed') native.storage.remove(PAY_OPEN_KEY);
    return Object.assign({ status }, result);
  },

  /**
   * A payment from an earlier checkout() that was confirmed only after that
   * call returned (the buyer closed the page early, or the provider was slow).
   * Resolves { status: 'paid', paymentId, amount, currency, provider } once,
   * or null. Call it when the cart or checkout screen opens.
   */
  async recover() {
    const open = native.storage.get(PAY_OPEN_KEY, null);
    if (!open || !open.paymentId) return null;
    let state;
    try {
      state = await payCall('status', { paymentId: open.paymentId });
    } catch (e) {
      return null;
    }
    if (state.status === 'pending' && Date.now() - open.at < 24 * 3600 * 1000) return null;
    native.storage.remove(PAY_OPEN_KEY);
    return state.status === 'paid'
      ? { status: 'paid', paymentId: open.paymentId, amount: open.amount, currency: open.currency, provider: open.provider }
      : null;
  },

  /** { status, amount, currency, provider } of one of this user's payments. */
  status(paymentId) {
    return payCall('status', { paymentId });
  },
};

// ---------------------------------------------------------------------
// Horizontal rows (.hscroll) run from screen edge to screen edge, so a
// scrolled item slides off the real edge instead of being clipped at the
// page inset, while the first item still starts where the content does.
// CSS alone breaks as soon as a screen pads its own wrapper or restyles the
// row, so the row is measured and fitted to the viewport here instead.
// ---------------------------------------------------------------------
const HSCROLL_MAX_INSET = 64;   // deeper than this, the row sits inside a card: leave it

function fitHscroll(row) {
  const s = row.style;
  for (const p of ['margin-left', 'margin-right', 'padding-left', 'padding-right', 'scroll-padding-left', 'scroll-padding-right']) {
    s.removeProperty(p);
  }
  // The row's natural content edges, before any bleed.
  s.setProperty('margin-left', '0px', 'important');
  s.setProperty('margin-right', '0px', 'important');
  s.setProperty('padding-left', '0px', 'important');
  s.setProperty('padding-right', '0px', 'important');
  const r = row.getBoundingClientRect();
  const width = document.documentElement.clientWidth;
  const left = Math.round(r.left);
  const right = Math.round(width - r.right);
  if (r.width === 0 || left < 0 || right < 0 || left > HSCROLL_MAX_INSET || right > HSCROLL_MAX_INSET) {
    for (const p of ['margin-left', 'margin-right', 'padding-left', 'padding-right']) s.removeProperty(p);
    return;
  }
  s.setProperty('margin-left', -left + 'px', 'important');
  s.setProperty('margin-right', -right + 'px', 'important');
  s.setProperty('padding-left', left + 'px', 'important');
  s.setProperty('padding-right', right + 'px', 'important');
  s.setProperty('scroll-padding-left', left + 'px', 'important');
  s.setProperty('scroll-padding-right', right + 'px', 'important');
}

// .bleed: the same measurement, but the element itself grows to the screen
// edges (a hero photo, a map) instead of padding its content back in.
function fitBleed(el) {
  const s = el.style;
  for (const p of ['margin-left', 'margin-right', 'margin-top', 'width', 'max-width']) s.removeProperty(p);
  s.setProperty('margin-left', '0px', 'important');
  s.setProperty('margin-right', '0px', 'important');
  s.setProperty('width', '100%', 'important');
  if (el.classList.contains('bleed-top')) s.setProperty('margin-top', '0px', 'important');
  const r = el.getBoundingClientRect();
  const width = document.documentElement.clientWidth;
  const left = Math.round(r.left);
  const right = Math.round(width - r.right);
  const top = Math.round(r.top + window.scrollY);
  if (r.width === 0 || left < 0 || right < 0 || left > HSCROLL_MAX_INSET || right > HSCROLL_MAX_INSET) {
    for (const p of ['margin-left', 'margin-right', 'margin-top', 'width']) s.removeProperty(p);
    return;
  }
  s.setProperty('margin-left', -left + 'px', 'important');
  s.setProperty('margin-right', -right + 'px', 'important');
  s.setProperty('width', `calc(100% + ${left + right}px)`, 'important');
  s.setProperty('max-width', 'none', 'important');
  if (el.classList.contains('bleed-top')) {
    if (top >= 0 && top <= HSCROLL_MAX_INSET) s.setProperty('margin-top', -top + 'px', 'important');
    else s.removeProperty('margin-top');
  }
}

let hscrollQueued = false;
function fitAllHscroll() {
  if (hscrollQueued) return;
  hscrollQueued = true;
  // A timer, not requestAnimationFrame: rAF never fires in a hidden screen
  // (a background tab kept alive), and those rows must be ready on return.
  setTimeout(() => {
    hscrollQueued = false;
    document.querySelectorAll('.hscroll').forEach(fitHscroll);
    document.querySelectorAll('.bleed').forEach(fitBleed);
  }, 0);
}

document.addEventListener('DOMContentLoaded', fitAllHscroll);
window.addEventListener('load', fitAllHscroll);
window.addEventListener('resize', fitAllHscroll);
window.addEventListener('native:resume', fitAllHscroll);
// Rows rendered later (lists filled after a fetch, a re-render on filter).
new MutationObserver((changes) => {
  for (const c of changes) {
    if (c.type === 'attributes' ? c.target.classList?.contains('hscroll') || c.target.classList?.contains('bleed')
      : [...c.addedNodes].some((n) => n.nodeType === 1 && (n.matches('.hscroll, .bleed') || n.querySelector?.('.hscroll, .bleed')))) {
      fitAllHscroll();
      return;
    }
  }
}).observe(document.documentElement, { childList: true, subtree: true, attributes: true, attributeFilter: ['class'] });

// ---------------------------------------------------------------------
// Scroll position for the native app bar: a large app bar shrinks to the
// small one as the page scrolls, like any native list. Only the first ~200px
// matter, so nothing is sent past that. The page never resizes while the bar
// collapses (the bar slides over room the stylesheet leaves at the top), so
// this cannot feed back into itself.
// ---------------------------------------------------------------------
const SCROLL_REPORT_MAX = 200;
let lastScrollSent = -1;
let scrollQueued = false;

function reportScroll() {
  scrollQueued = false;
  const y = Math.max(0, Math.round(window.scrollY || document.documentElement.scrollTop || 0));
  const value = Math.min(y, SCROLL_REPORT_MAX);
  if (value === lastScrollSent) return;
  lastScrollSent = value;
  send({ action: 'scroll', y: value });
}

function queueScrollReport() {
  if (scrollQueued) return;
  scrollQueued = true;
  // A timer, not rAF, so a screen scrolled while hidden still reports.
  setTimeout(reportScroll, 16);
}

window.addEventListener('scroll', queueScrollReport, { passive: true });
window.addEventListener('native:resume', () => { lastScrollSent = -1; queueScrollReport(); });
window.addEventListener('load', queueScrollReport);

// Tell the shell the page is ready, so it can hide the loading overlay.
window.addEventListener('load', () => send({ action: 'ready' }));

// The shell keeps each screen's WebView alive, so a screen is NOT reloaded
// when you return to it from a pushed route or another tab. Anything that
// reads changing data must re-read it here.
//
//   window.addEventListener('native:resume', render);
//
// The shell dispatches this event when the screen becomes visible again.
window.native = native;
